@startuml

class Bookmaker {
  + name : string
  + AcceptBets(bet: Bet) : void
  + CalculateWinningsAndLosses() : double
}

class Bettor {
  + name : string
  + placeBet(bet: Bet) : void
}

class Race {
  + runners : Runner[]
  + winner : Runner
  + DetermineWinner() : void
}

class Runner {
  + horseName : string
  + jockey : Jockey
}

class Jockey {
  + name : string
}

class Bet {
  + amount : double
  + odds : double
  + race : Race
  + runner : Runner
}

Bookmaker "1" -- "*" Bettor : manages
Bettor "0..*" -- "1" Bet : places
Race "1" -- "*" Runner : has
Runner "1" -- "1" Jockey : riddenBy
Bet "1" -- "1" Race : refersTo
Bet "1" -- "1" Runner : on

@enduml

